static int glyph_index(char c) {
    int i;
    if (c >= 'a' && c <= 'z') c = (char)(c - 'a' + 'A');
    for (i = 0; g_charset[i]; i++)
        if (g_charset[i] == c) return i;
    return -1;
}

int se_frame_text_width(const char *text, int scale) {
    int i, w = 0;
    if (!text || scale < 1) return 0;
    for (i = 0; text[i]; i++) {
        int gi = glyph_index(text[i]);
        w += gi >= 0 ? g_font_w[gi] : 8;
    }
    return w * scale;
}

void se_frame_contrast(const uint8_t bg[3], uint8_t fg[3]) {
    int y = (299 * bg[0] + 587 * bg[1] + 114 * bg[2]) / 1000;
    uint8_t v = y > 140 ? 0 : 255;
    fg[0] = fg[1] = fg[2] = v;
}

void se_frame_fill_row(uint8_t *row, int width, const se_frame *f) {
    int x;
    for (x = 0; x < width; x++) {
        row[x * 3 + 0] = f->bg[0];
        row[x * 3 + 1] = f->bg[1];
        row[x * 3 + 2] = f->bg[2];
    }
}

void se_frame_edge_row(uint8_t *row, int width, const se_frame *f) {
    int x;
    for (x = 0; x < width; x++) {
        row[x * 3 + 0] = (uint8_t)((f->bg[0] * 4 + f->fg[0]) / 5);
        row[x * 3 + 1] = (uint8_t)((f->bg[1] * 4 + f->fg[1]) / 5);
        row[x * 3 + 2] = (uint8_t)((f->bg[2] * 4 + f->fg[2]) / 5);
    }
}

/* Blend one coverage value into a pixel. */
static void blend(uint8_t *p, const uint8_t fg[3], int a) {
    p[0] = (uint8_t)((fg[0] * a + p[0] * (255 - a) + 127) / 255);
    p[1] = (uint8_t)((fg[1] * a + p[1] * (255 - a) + 127) / 255);
    p[2] = (uint8_t)((fg[2] * a + p[2] * (255 - a) + 127) / 255);
}

static void text_row(uint8_t *row, int width, int y, int ytop, int scale,
                     const char *text, int x0, const uint8_t fg[3]) {
    int gy, x, i, sx, sy;
    if (!text || y < ytop) return;
    gy = (y - ytop) / scale;
    if (gy < 0 || gy >= FONT_H) return;
    x = x0;
    for (i = 0; text[i]; i++) {
        int gi = glyph_index(text[i]);
        int gw;
        if (gi < 0) { x += 8 * scale; continue; }
        gw = g_font_w[gi];
        for (sx = 0; sx < gw; sx++) {
            int a = g_font[gi][gy][sx];
            if (!a) continue;
            for (sy = 0; sy < scale; sy++) {
                int px = x + sx * scale + sy;
                if (px < 0 || px >= width) continue;
                blend(row + px * 3, fg, a);
            }
        }
        x += g_font_w[gi] * scale;
    }
}

static void logo_row(uint8_t *row, int width, int y, int ytop, int x0,
                     const uint8_t fg[3]) {
    int gy, gx;
    if (y < ytop) return;
    gy = y - ytop;
    if (gy < 0 || gy >= LOGO_H) return;
    for (gx = 0; gx < LOGO_W; gx++) {
        int a = g_logo[gy][gx];
        int px = x0 + gx;
        if (!a || px < 0 || px >= width) continue;
        blend(row + px * 3, fg, a);
    }
}

static void brand_row(uint8_t *row, int width, int y, int ytop, int x0,
                      int idx, const uint8_t fg[3]) {
    int gy, gx;
    if (idx < 0 || idx >= BRAND_N || y < ytop) return;
    gy = y - ytop;
    if (gy < 0 || gy >= BRAND_SZ) return;
    for (gx = 0; gx < BRAND_SZ; gx++) {
        int a = g_brand[idx][gy][gx];
        int px = x0 + gx;
        if (!a || px < 0 || px >= width) continue;
        blend(row + px * 3, fg, a);
    }
}

static void sprite_row(uint8_t *row, int width, int y, int ay, int ax,
                       int aw, int ah, const uint8_t *sp, int sw, int sh) {
    int gy, gx;
    if (!sp || y < ay || y >= ay + ah) return;
    gy = ((y - ay) * sh) / ah;
    if (gy < 0 || gy >= sh) return;
    for (gx = 0; gx < aw; gx++) {
        int sx = (gx * sw) / aw;
        const uint8_t *p = sp + ((size_t)gy * sw + sx) * 3;
        int px = ax + gx;
        if (!(p[0] | p[1] | p[2])) continue;
        if (px < 0 || px >= width) continue;
        row[px * 3 + 0] = p[0];
        row[px * 3 + 1] = p[1];
        row[px * 3 + 2] = p[2];
    }
}

void se_frame_layout(se_frame *f) {
    int pad = 10;
    int inner_h = f->inner_h > 0 ? f->inner_h : 150;
    int art_h = f->sprite ? inner_h : 0;    /* the art fills the band */
    int brand_h = f->brand_i >= 0 ? BRAND_SZ : 0;
    int tall = inner_h;
    (void)0;
    if (art_h > tall) tall = art_h;
    if (LOGO_H > tall) tall = LOGO_H;
    (void)brand_h;
    f->scale = 1;
    f->top = pad;
    f->bottom = tall + 2 * pad;
}

void se_frame_top_row(uint8_t *row, int width, const se_frame *f, int y) {
    (void)y;
    se_frame_fill_row(row, width, f);
}

void se_frame_bottom_row(uint8_t *row, int width, const se_frame *f, int y) {
    int pad = 10;
    int inner = f->bottom - 2 * pad;
    int mid_h = LOGO_H + 4 + FONT_H + 2 + FONT_H;  /* Canon, model, lens */
    int logo_top = pad + (inner - mid_h) / 2;
    int model_top = logo_top + LOGO_H + 4;
    int lens_top = model_top + FONT_H + 2;
    int label_top = pad;
    int value_top = label_top + FONT_H + 4;
    int cw[3], total = 0, gap = 14, x, i, sw, left_w;

    se_frame_fill_row(row, width, f);

    /* stock: the brand's square mark, or the canister when there is no mark */
    if (f->brand_i >= 0) {
        int by = pad + (inner - BRAND_SZ) / 2;
        if (by < 0) by = 0;
        int sy = by + BRAND_SZ + 2;
        brand_row(row, width, y, by, pad, f->brand_i, f->brand_fg);
        {
            int sw2 = se_frame_text_width(f->stock, 1);
            if (sw2 && sy + FONT_H <= f->bottom)
                text_row(row, width, y, sy, 1, f->stock, pad, f->fg);
        }
        left_w = BRAND_SZ;
    } else if (f->sprite && f->sprite_w > 0 && f->sprite_h > 0) {
        int sw0 = se_frame_text_width(f->stock, 1);
        int ah = inner - (sw0 ? FONT_H + 4 : 0);
        int aw = (f->sprite_w * ah) / f->sprite_h;
        sprite_row(row, width, y, pad, pad, aw, ah,
                   f->sprite, f->sprite_w, f->sprite_h);
        {
            int sw2 = se_frame_text_width(f->stock, 1);
            if (sw2 && pad + ah + 2 + FONT_H <= f->bottom)
                text_row(row, width, y, pad + ah + 2, 1, f->stock, pad, f->fg);
        }
        left_w = aw;
    } else {
        left_w = 0;
    }

    /* the camera mark, centred */
    logo_row(row, width, y, logo_top, (width - LOGO_W) / 2, f->brand_colour);
    {
        int mw = se_frame_text_width(f->model, 1);
        int lw = se_frame_text_width(f->lens, 1);
        text_row(row, width, y, model_top, 1, f->model, (width - mw) / 2, f->dim);
        if (lw)
            text_row(row, width, y, lens_top, 1, f->lens, (width - lw) / 2, f->dim);
    }

    /* the stock, centred between the camera block and the exposure block */
    /* the stock name, under the brand mark, when there is no mark */
    sw = f->brand_i >= 0 ? 0 : (f->sprite ? 0 : se_frame_text_width(f->stock, 1));
    if (sw && left_w == 0) {
        int sx = pad;
        text_row(row, width, y, label_top + FONT_H + 4, 1, f->stock, sx, f->fg);
    }

    for (i = 0; i < 3; i++) {
        int wl = se_frame_text_width(f->label[i], 1);
        int wv = se_frame_text_width(f->value[i], 1);
        cw[i] = wl > wv ? wl : wv;
        total += cw[i];
    }
    total += 2 * gap;
    x = width - pad - total;
    if (x < pad) x = pad;
    for (i = 0; i < 3; i++) {
        int wl = se_frame_text_width(f->label[i], 1);
        int wv = se_frame_text_width(f->value[i], 1);
        text_row(row, width, y, label_top, 1, f->label[i], x + (cw[i] - wl) / 2, f->dim);
        text_row(row, width, y, value_top, 1, f->value[i], x + (cw[i] - wv) / 2, f->fg);
        x += cw[i] + gap;
    }
}
